import type { MetadataRoute } from 'next';

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'SheetFlow AI',
    short_name: 'SheetFlow',
    description:
      'SheetFlow builds AI automations that capture leads, follow up on WhatsApp, book appointments, and keep your CRM updated — so your business runs itself.',
    start_url: '/',
    display: 'standalone',
    background_color: '#060608',
    theme_color: '#060608',
    // Generated by scripts/build-brand-assets.mjs, so the declared sizes are
    // the real ones. Installability needs a square 192 and 512; the maskable
    // entry keeps the mark inside the safe zone on platforms that crop to a
    // squircle, which the previous 248x252 source could not satisfy.
    icons: [
      { src: '/brand/raster/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/brand/raster/lockup-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      {
        src: '/brand/raster/icon-maskable-512.png',
        sizes: '512x512',
        type: 'image/png',
        purpose: 'maskable',
      },
    ],
  };
}
